<script setup lang="ts">
import{computed,ref}from'vue';import{useRouter}from'vue-router';import{state,refreshMine}from'../store';import{api,run}from'../api';import type{Equipment}from'../types';import Icon from'../components/Icon.vue'
const router=useRouter(),query=ref(''),category=ref('全部器材'),selected=ref<Equipment|null>(null),busy=ref(false),quantity=ref(1),purpose=ref(''),dueDate=ref('')
const filtered=computed(()=>state.equipment.filter(e=>(category.value==='全部器材'||e.category===category.value)&&[e.name,e.assetCode,e.description].join('').includes(query.value)))
function open(e:Equipment){if(!state.user){router.push({path:'/login',query:{redirect:'/equipment'}});return}selected.value=e;quantity.value=1;purpose.value='';dueDate.value=''}
async function submit(){if(!selected.value||!purpose.value.trim()||!dueDate.value)return;busy.value=true;await run(async()=>{await api('/loans','POST',{equipmentId:selected.value!.id,quantity:quantity.value,purpose:purpose.value,dueDate:dueDate.value});await refreshMine();selected.value=null},'借用申请已提交，审核通过后领取');busy.value=false}
const disabledDate=(d:Date)=>d.getTime()<new Date().setHours(0,0,0,0)||d.getTime()>Date.now()+90*86400000
</script>
<template><div class="page-content"><div class="page-heading"><div><div class="eyebrow">共享资源，创造更多可能</div><h1>器材借用<span class="greeting-dot">.</span></h1><p>把资源共享起来，让每一个好点子顺利发生。</p></div><router-link to="/center?tab=loans" class="outline-link"><Icon name="clipboard" :size="17"/>我的借还记录<Icon name="arrowup" :size="16"/></router-link></div><div class="service-process panel"><span><b>01</b>选择器材</span><Icon name="right"/><span><b>02</b>提交申请</span><Icon name="right"/><span><b>03</b>审核后领取</span><Icon name="right"/><span><b>04</b>申请归还并验收</span></div><div class="filter-bar"><div class="filter-tabs"><button v-for="c in ['全部器材',...new Set(state.equipment.map(e=>e.category))]" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><el-input v-model="query" placeholder="搜索器材名称或资产编号" clearable class="list-search"><template #prefix><Icon name="search" :size="16"/></template></el-input></div><div class="equipment-grid"><article v-for="e in filtered" :key="e.id" class="panel equipment-card"><div class="equipment-art" :class="{'art-peach':e.category==='户外装备','art-purple':e.category==='运动器材'}"><Icon :name="e.category==='摄影器材'?'camera':e.category==='户外装备'?'tent':e.category==='运动器材'?'racket':e.name.includes('麦克风')?'mic':e.name.includes('投影')?'monitor':'package'" :size="64"/><span>{{e.assetCode}}</span></div><div class="equipment-body"><span class="category-label">{{e.category}}</span><h3>{{e.name}}</h3><p>{{e.description}}</p><div class="equipment-location"><Icon name="pin" :size="15"/>{{e.location}}</div><div class="equipment-card-footer"><span><i :class="{'no-stock':e.availableQuantity===0}"/>可用 <b>{{e.availableQuantity}}</b> / {{e.totalQuantity}} 件</span><el-button type="primary" plain :disabled="e.availableQuantity<1" @click="open(e)">{{e.availableQuantity>0?'申请借用':'暂无库存'}}</el-button></div></div></article></div><el-empty v-if="!filtered.length" description="暂未找到匹配器材"/></div>
<el-dialog :model-value="!!selected" @update:model-value="(v:boolean)=>{if(!v)selected=null}" :title="'借用申请 · '+(selected?.name||'')" width="min(550px, 94vw)"><el-form label-position="top" @submit.prevent="submit"><div class="info-box">审核通过后请前往 {{selected?.location}} 领取；归还时由管理员验收并恢复库存。</div><el-form-item label="借用数量" required><el-input-number v-model="quantity" :min="1" :max="selected?.availableQuantity||1"/></el-form-item><el-form-item label="预计归还日期" required><el-date-picker v-model="dueDate" type="date" value-format="YYYY-MM-DD" :disabled-date="disabledDate" placeholder="请选择 90 天内的日期" class="full-width"/></el-form-item><el-form-item label="借用用途" required><el-input v-model="purpose" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="请说明借用用途、相关活动等"/></el-form-item></el-form><template #footer><el-button @click="selected=null">取消</el-button><el-button type="primary" :loading="busy" :disabled="!purpose.trim()||!dueDate" @click="submit">提交借用申请</el-button></template></el-dialog></template>
